port.before:
    if(b_pse)
    {
        int busy_retry_times = 2;
        do{
            ret = sgx_create_pse_session();
        }while (ret == SGX_ERROR_BUSY && busy_retry_times--);
        if (ret != SGX_SUCCESS)
            return ret;
    }
#ifdef SUPPLIED_KEY_DERIVATION
    ret = sgx_ra_init_ex(pub_key, b_pse, key_derivation, p_context);
#else
    ret = sgx_ra_init(pub_key, b_pse, p_context);
#endif
    if(b_pse)
    {
        sgx_close_pse_session();
        return ret;
    }

port.after:
    if (b_pse) return SGX_ERROR_FEATURE_NOT_SUPPORTED;
#ifdef SUPPLIED_KEY_DERIVATION
#error Custom key derivation is outside this configured integration
#else
    ret = sgx_ra_init(pub_key, 0, p_context);
#endif
